const re = /^Required Fields Completed:\s*(\d+)\s+of\s+(\d+)$/;
const anyRequired = cards.some(c => {
  const m = leaves(c).map(t => t.match(re)).find(Boolean);
  return !!m && Number(m[2]) > 0;
});
